import{_ as a,c as i,o as e,H as t}from"./chunks/framework.B03ETCDl.js";const d=JSON.parse('{"title":"스프링 캐시에 대해서 고민해보자","description":"","frontmatter":{"title":"스프링 캐시에 대해서 고민해보자","date":"2025-02-23T12:00+09:00","tags":["Spring Boot","Caffeine Cache"]},"headers":[],"relativePath":"posts/spring-cache.md","filePath":"posts/spring-cache.md","lastUpdated":1779711618000}'),n={name:"posts/spring-cache.md"};function h(l,s,p,k,r,c){return e(),i("div",null,[...s[0]||(s[0]=[t(`<p>스프링 프레임워크 기반의 애플리케이션은 <strong>캐시 추상화</strong>를 제공하여 캐시 관련 모듈에 대한 의존성을 추가하고 <u>@EnableCaching</u>과 같은 어노테이션으로 <strong>선언적 캐시</strong>를 간단하게 적용할 수 있습니다. 스프링을 다루는 많은 개발자들이 일부 비즈니스 로직의 성능 향상을 위해서 자주 사용되겠지만 생각보다 도입이 간단한 점으로 인해 여러가지 부분들을 신경쓰지 않고 사용하고 있을 가능성이 높다고 생각합니다. 개인적인 경험을 토대로 <strong>스프링 캐시를 활용하는 경우에 어떤 부분들을 고민하면 좋은지</strong> 다루어보고자 합니다.</p><h4 id="캐시-프로바이더와-다양한-캐시-전략을-검토해야" tabindex="-1">캐시 프로바이더와 다양한 캐시 전략을 검토해야 <a class="header-anchor" href="#캐시-프로바이더와-다양한-캐시-전략을-검토해야" aria-label="Permalink to &quot;캐시 프로바이더와 다양한 캐시 전략을 검토해야&quot;">​</a></h4><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">spring.cache</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">caffeine</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  caffeine.spec</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">maximumSize=1000,expireAfterAccess=PT5M</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  cache-names</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">category, book</span></span></code></pre></div><p>단일 인스턴스로 운용되는 애플리케이션에서도 레디스와 같은 외부 메모리 저장소를 의존하기도 하는데 스케일 아웃이 되지 않을 가능성이 높다면 차라리 Caffeine 과 같은 로컬 캐시 프로바이더를 선택하고 프로바이더마다 적용할 수 있는 <strong>다양한 캐시 전략을 검토</strong>하는 것이 좋습니다. Caffeine을 도입하더라도 기본 예제에서 소개되는 <a href="https://github.com/ben-manes/caffeine/wiki/Specification" target="_blank" rel="noreferrer">CaffeineSpec</a>을 개발 시 뿐만 아니라 <u>운영환경에서 그대로 사용할 가능성</u>도 높습니다. 또한, 캐시마다 효율적인 전략이 다양하므로 스프링 부트 자동 설정에 의한 <u>단일 전략보다는 캐시 별 전략을 별도로 사용하도록 직접 구성</u>하는게 좋을 것 같습니다.</p><h4 id="cacheable-키-구성을-확인해야" tabindex="-1">@Cacheable 키 구성을 확인해야 <a class="header-anchor" href="#cacheable-키-구성을-확인해야" aria-label="Permalink to &quot;@Cacheable 키 구성을 확인해야&quot;">​</a></h4><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">logging.level.org.springframework.cache</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">trace</span></span></code></pre></div><p>기본적으로 <u>CacheInterceptor</u>에 대한 로그 레벨을 <strong>TRACE</strong>로 지정해두지 않기 때문에 @Cacheable에 정의한 키에 대해서 검토하지 않고 캐시되는지 여부만 확인하여 <strong>잘못된 키로 캐시되어도 무시되고 있을 가능성</strong>이 높습니다. 또한, 주로 키를 구성할 때 <u>#root.methodName</u> 만 사용해버리면 키 중복 발생이 높아지고 <u>ClassCastException</u>이 발생할 수 있는데 다음과 같이 항상 서비스 클래스 이름도 키 구성에 포함하는 것을 추천합니다. 또한, 키 정의 시 사용해야할 파라미터 수가 많다면 나열하기 보다는 <u>KeyGenerator</u> 인터페이스 구현체를 만들어서 사용하는 것이 더 간단합니다.</p><div class="language-java vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">@</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">Cacheable</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cacheNames</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;[cache-name]&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">key</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;T(String).join(&#39;:&#39;, #root.targetClass.simpleName, #root.methodName)&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><blockquote><p>캐시에 대한 키 정의 시 중복에 대한 부분은 런타임 예외로 발생하기 때문에 사전에 인지하기 어려운 부분이기 때문에 주의해야할 부분입니다.</p></blockquote><h4 id="cacheevict-에서-전체-삭제를-해야할까" tabindex="-1">@CacheEvict 에서 전체 삭제를 해야할까 <a class="header-anchor" href="#cacheevict-에서-전체-삭제를-해야할까" aria-label="Permalink to &quot;@CacheEvict 에서 전체 삭제를 해야할까&quot;">​</a></h4><div class="language-java vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">@</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">CacheEvict</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cacheNames</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;[cache-name]&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">allEntries</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>우리가 캐시되어진 일부 데이터가 갱신되어야할 때 <a href="https://www.baeldung.com/spring-boot-evict-cache" target="_blank" rel="noreferrer">@CacheEvict</a>와 함께 <u>allEntries</u> 속성을 사용하여 동일한 캐시 이름을 가진 모든 데이터를 삭제하게 됩니다. 개발자 입장에서 간단하고 편리해보이지만 캐시 이름에 대해 저장되는 키 패턴이 다양해지는 경우에 특정 키 패턴으로 구성된 일부 데이터만 갱신하면 되지만 <u>모든 데이터가 삭제되어 GC 부하 뿐만 아니라 나머지 데이터에 대한 DB 부하도 다시 발생한다</u>는 점을 생각해보게 됩니다. @CacheEvict 에서 키 패턴에 의해 삭제하는 방법을 지원하지 않기 때문에 직접 별도로 AOP로 구현해야합니다.</p><h4 id="자체-호출에-의한-캐시가-적용되지-않음" tabindex="-1">자체 호출에 의한 캐시가 적용되지 않음 <a class="header-anchor" href="#자체-호출에-의한-캐시가-적용되지-않음" aria-label="Permalink to &quot;자체 호출에 의한 캐시가 적용되지 않음&quot;">​</a></h4><p>인텔리제이 IDE 에서 자체 호출에 대한 코드가 발생하는 경우 친절하게 <u>@Cacheable 자기 호출(실질적으로 타깃 객체 내의 메서드가 타깃 객체 내의 다른 메서드를 호출) 입니다. 캐시 어노테이션이 런타임 시에 무시됩니다</u>라는 문구로 경고해주고 있습니다. 이와 같이 스프링 캐시 어노테이션에 의한 선언적 캐시는 스프링 AOP를 통해 프록시로 동작하므로 <u>자체 호출(Self Invocation)에 의해서</u>는 적용되지 않습니다. 따라서, 자체 호출로 남지 않도록 코드 리뷰를 수행해야하고 <a href="https://www.baeldung.com/spring-self-injection" target="_blank" rel="noreferrer">Self-Injection</a> 또는 자체 호출이 되지 않는 구조로 리팩토링 해야합니다.</p><h4 id="애플리케이션-캐시-부하-모니터링" tabindex="-1">애플리케이션 캐시 부하 모니터링 <a class="header-anchor" href="#애플리케이션-캐시-부하-모니터링" aria-label="Permalink to &quot;애플리케이션 캐시 부하 모니터링&quot;">​</a></h4><div class="language-java vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">CaffeineCache cache </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (CaffeineCache) cacheManager.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">getCache</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;sample&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">log.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">info</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;sample - {}&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, cache.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">getNativeCache</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">().</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">stats</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">());</span></span></code></pre></div><p>서비스 회사의 개발 조직처럼 애플리케이션 모니터링을 지속적으로 수행하지 않는 개발자 입장에서는 선언적 캐시 적용으로 인해 발생할 수 있는 애플리케이션 부하를 검토하지 않고 자연스레 무시될 가능성이 높습니다. 애플리케이션에 다양한 기능을 추가하면서 캐시를 도입하다보면 서로 다른 캐시로 인해 애플리케이션에서 정의한 캐시 제한량을 넘어서거나 캐시가 무의미하게 저장되고 삭제되는 것이 반복될 수 있습니다. 만약, Caffiene 캐시를 도입한다면 <u>recordStats</u> 옵션을 사용하고 캐시에 대한 통계를 주기적으로 모니터링할 수 있는 로그를 남기는게 좋습니다.</p><p>마지막으로, 애플리케이션에서 로컬 캐시로 충분한대도 불구하고 무작정 레디스라는 외부 캐시 저장소 기술에 의존하고 있는지 다시한번 생각해보도록 합시다.</p>`,18)])])}const g=a(n,[["render",h]]);export{d as __pageData,g as default};
